import{c as e,Q as s,j as a,m as r}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Nick Dobos：Dynamic Workflows 是 RLM（Runtime-Level Meta-programming）","description":"","frontmatter":{"url":"https://x.com/NickADobos/status/2060106494742516218","title":"Nick Dobos：Dynamic Workflows 是 RLM（Runtime-Level Meta-programming）","author":"Nick Dobos","archived":"2026-06-15T00:00:00.000Z","handle":"@NickADobos","published":"2026-05-28T00:00:00.000Z","score":"6.6/10","stats":"551 likes · 37 retweets","tags":["dynamic-workflows","RLM","scaling-law","meta-programming","deep-analysis"],"type":"tweet"},"headers":[],"relativePath":"research/tweets/2026-05-28-@NickADobos-516218.md","filePath":"research/tweets/2026-05-28-@NickADobos-516218.md","lastUpdated":1785909234000}'),o={name:"research/tweets/2026-05-28-@NickADobos-516218.md"};function n(i,t,d,l,m,c){return s(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="nick-dobos-dynamic-workflows-是-rlm-runtime-level-meta-programming" tabindex="-1">Nick Dobos：Dynamic Workflows 是 RLM（Runtime-Level Meta-programming） <a class="header-anchor" href="#nick-dobos-dynamic-workflows-是-rlm-runtime-level-meta-programming" aria-label="Permalink to &quot;Nick Dobos：Dynamic Workflows 是 RLM（Runtime-Level Meta-programming）&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/NickADobos/status/2060106494742516218" target="_blank" rel="noreferrer">https://x.com/NickADobos/status/2060106494742516218</a><strong>作者</strong>：Nick Dobos（@NickADobos） <strong>發布日期</strong>：2026-05-28 <strong>收錄日期</strong>：2026-06-15 <strong>類型</strong>：tweet <strong>統計</strong>：551 likes · 37 retweets</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Claude code&#39;s new dynamic workflows update is absurd.</p><p>Make sure you understand what its doing here. This isn&#39;t simply a long running mode like /goal, or a fancy subagent verifier process.</p><p>This is Claude vibecoding an entire brand new subagent fleet harness on demand</p><p>RLM on agent harnesses. Thats what &quot;dynamic workflow&quot; means.</p><p>This is basically a new scaling law dimension.</p><p>Base Model Compute × Inference time Thinking Compute × Inference time generated Harness Compute</p><p>HUGE step forward on this third dimension.</p><p>Think about it: before, the harness was fixed (skills, subagents, agent teams).</p><p>Now Claude <em>writes</em> the harness itself.</p><p>The harness IS the output. Then the harness runs agents. That&#39;s 3 levels deep.</p><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>4/10</td><td>純概念分析，無直接操作指引可套用</td></tr><tr><td>B. 創新性 (20%)</td><td>10/10</td><td>全網首創 RLM 框架，提出第三個 scaling law 維度</td></tr><tr><td>C. 證據品質 (20%)</td><td>5/10</td><td>理論推演，無實驗數據支撐</td></tr><tr><td>D. 技術深度 (15%)</td><td>9/10</td><td>深度架構分析，3層遞歸（模型→Harness→Agents）結構清晰</td></tr><tr><td>E. 泛化性 (15%)</td><td>7/10</td><td>幫助理解整體框架設計哲學，但不直接轉化為操作</td></tr><tr><td><strong>加權總分</strong></td><td><strong>6.6/10</strong></td><td>A×0.3+B×0.2+C×0.2+D×0.15+E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Agent <strong>理由</strong>：RLM 框架是理解 dynamic workflow 設計哲學的最佳概念模型，適合放入 harness-meta 的理論背景章節。</p>',18)])])}const g=e(o,[["render",n]]);export{p as __pageData,g as default};
